using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsPavingReview{
 [Serializable]class Probe{public string kind;public float x,y,z;public bool hit;}[Serializable]class Probes{public Probe[] probes;}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static void Shot(Camera c,Vector3 from,Vector3 target,string file){c.transform.position=from;c.transform.LookAt(target);var rt=new RenderTexture(960,720,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(960,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,960,720),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}
 public static void Run(){const string ev="Evidence/Target25Paving";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget25Output/Room.unity");Physics.SyncTransforms();var intact=GameObject.Find("ruins_26");var broken=GameObject.Find("ruins_27");Check(intact&&broken,"Formal paving missing");var data=JsonUtility.FromJson<Probes>(File.ReadAllText("Assets/Editor/paving-probes.json"));Check(data.probes.Length==2048,"Missing floor probes");float max=0;
 foreach(var p in data.probes){var go=p.kind=="paving"?intact:broken;var co=go.GetComponent<MeshCollider>();Check(co.sharedMesh==go.GetComponent<MeshFilter>().sharedMesh,"Visual collider identity");bool hit=co.Raycast(new Ray(go.transform.TransformPoint(new Vector3(p.x,1,p.z)),Vector3.down),out var h,2);Check(hit==p.hit,"Paving opening mismatch "+p.kind+" "+p.x+","+p.z);if(hit){float d=Mathf.Abs(h.point.y-go.transform.position.y-p.y);max=Mathf.Max(max,d);Check(d<.001,"Floor height mismatch");}}
 foreach(float z in new[]{-.3f,1f})foreach(float sign in new[]{-1f,1f}){var actor=new GameObject("Paving walk diagnostic");actor.transform.position=new Vector3(sign>0?-10.5f:-5.5f,3.05f,z);var cc=actor.AddComponent<CharacterController>();cc.radius=.25f;cc.height=1.6f;cc.center=Vector3.up*.8f;cc.stepOffset=.3f;cc.skinWidth=.01f;cc.minMoveDistance=0;for(int i=0;i<50;i++)cc.Move(new Vector3(sign*.1f,-.035f,0));Check(sign>0?actor.transform.position.x>-5.6f:actor.transform.position.x<-10.4f,"Paving controller catches on seam/edge");UnityEngine.Object.DestroyImmediate(actor);}
 foreach(var template in new[]{intact,broken})foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(i=>{var g=UnityEngine.Object.Instantiate(template);g.transform.position=new Vector3(80+(i%15)*3,3,80+(i/15)*3);return g;}).ToArray();Check(clones.Select(g=>g.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(g=>g.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1&&clones.All(g=>g.GetComponent<MeshCollider>().sharedMesh==template.GetComponent<MeshFilter>().sharedMesh),"Paving reference sharing");foreach(var g in clones)UnityEngine.Object.DestroyImmediate(g);}
 var c=UnityEngine.Object.FindAnyObjectByType<Camera>();c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);RenderSettings.ambientLight=Color.gray*.65f;var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);
 Shot(c,new Vector3(-11,6,5),new Vector3(-8,3.05f,0),ev+"/paving-close.png");Shot(c,new Vector3(-13,12,10),new Vector3(-6,3.3f,0),ev+"/paving-game.png");Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/mixed-game.png");sun.transform.rotation=Quaternion.Euler(25,140,0);Shot(c,new Vector3(-11,6,5),new Vector3(-8,3.05f,0),ev+"/paving-opposite.png");
 var pieces=Enumerable.Range(26,4).Select(i=>GameObject.Find("ruins_"+i).GetComponent<MeshRenderer>()).ToArray();var old=pieces.Select(o=>o.sharedMaterial).ToArray();var gray=new Material(Shader.Find("Universal Render Pipeline/Lit"));gray.SetColor("_BaseColor",Color.gray);gray.SetFloat("_Smoothness",.15f);foreach(var r in pieces)r.sharedMaterial=gray;sun.transform.rotation=Quaternion.Euler(38,-28,0);Shot(c,new Vector3(-11,6,5),new Vector3(-8,3.05f,0),ev+"/paving-mono.png");for(int i=0;i<4;i++)pieces[i].sharedMaterial=old[i];UnityEngine.Object.DestroyImmediate(gray);
 File.WriteAllText(ev+"/result.json","{\"pass\":true,\"formalKinds\":2,\"floorAndHoleProbes\":2048,\"maxDelta\":"+max.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"actualControllerCrossings\":4,\"meshMaterialShared9And225EachKind\":true,\"gpuMeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
